from lib import *
S = SS('v89')
steps = [
    step("先看最裸的滚动发布:没有 readinessProbe、没有 preStop、应用收到 SIGTERM 立刻退出,应用启动要 3 s 才开始监听。3 副本,maxSurge 1、maxUnavailable 0,客户端在集群里经 Service 以约 100 个请求/秒访问。结果 1173 个请求里失败 157 个(13.38%):refused 126、timeout 31,第一个到最后一个失败相隔 4.0 s。kubectl rollout 只用了 1 s 就报告完成,因为没有 readinessProbe,新 Pod 一启动就算 Ready;客户端最后一次收到 v1 在 6.4 s,第一次收到 v2 在 8.8 s,中间 2.41 s 没有任何成功响应。", t=tl(S(1)), mark=lidx(S(1), '客户端请求 1173'), b=bars([['请求总数', 1173, '1173'], ['失败', 157, '157(13.38%)'], ['refused', 126, '126'], ['timeout', 31, '31']], 1173, mark=[1, 2, 3], cur=[0]), kv=KV([['rollout 耗时', '1 s(没有 readiness)'], ['无成功响应的间隔', '2.41 s'], ['失败类型', 'refused 126 / timeout 31'], ['失败率', '13.38%']], ['失败率'])),
    step("加上 readinessProbe(httpGet /,每秒一次)。新 Pod 没开始监听就不会收到流量,启动阶段的失败基本消失:refused 从 126 降到 4,最长无成功响应的间隔降到 0.11 s。但旧 Pod 被终止时仍有失败:2229 个请求失败 65 个(2.92%),reset 16、timeout 45,其中 /slow 请求失败 16 个,与 reset 的数量相同,我认为是正在处理的慢请求被进程退出打断,没有逐条核对。第一个到最后一个失败相隔 9.6 s,kubectl rollout 用了 13 s。timeout 的原因是推测:旧 Pod 已经删掉,往它的 IP 发的连接没有回应,没有抓包验证。", t=tl(S(2)), mark=lidx(S(2), '客户端请求 2229'), b=bars([['请求总数', 2229, '2229'], ['失败', 65, '65(2.92%)'], ['timeout', 45, '45'], ['reset', 16, '16'], ['refused', 4, '4']], 2229, mark=[1, 2, 3], done=[4], cur=[0]), kv=KV([['refused', '126 → 4(readiness 的效果)'], ['剩下的失败', '终止阶段:timeout 45 / reset 16'], ['/slow 失败', '16(与 reset 数量相同)'], ['rollout 耗时', '13 s']], ['剩下的失败'])),
    step("再加 preStop sleep 5(readinessProbe 保留,应用仍然收到 SIGTERM 就立刻退出)。2495 个请求失败 0 个。preStop 让 Pod 在被摘出 Service 的这段时间里继续活着:SIGTERM 要等 5 s 的钩子结束才发,而端点摘除在这段时间里传播到各节点。kubectl rollout 用了 12 s。这是单次运行,0 个失败只说明这次没有失败,不是保证。", t=tl(S(3)), mark=lidx(S(3), '客户端请求 2495'), done=lidx(S(3), '客户端请求 2495'), b=bars([['请求总数', 2495, '2495'], ['失败', 0, '0']], 2495, done=[1], cur=[0]), kv=KV([['失败', '0 / 2495'], ['rollout 耗时', '12 s'], ['原理', '钩子期间端点摘除传播完成'], ['次数', '只跑了一次']], ['失败'])),
    step("不用 preStop,而是让应用自己优雅退出:收到 SIGTERM 后继续服务,响应带 Connection: close,空闲 1 s 才退出。2464 个请求失败 0 个,rollout 12 s。这个结果依赖我手写的退出逻辑:它只在 1 s 没有新请求之后才退出,等价于在等端点摘除传播完成;如果流量断断续续,这个启发式不可靠,没有测。", t=tl(S(4)), mark=lidx(S(4), '客户端请求 2464'), done=lidx(S(4), '客户端请求 2464'), b=bars([['请求总数', 2464, '2464'], ['失败', 0, '0']], 2464, done=[1], cur=[0]), kv=KV([['失败', '0 / 2464'], ['rollout 耗时', '12 s'], ['退出条件', '空闲 1 s(手写启发式)'], ['没测', '流量断断续续的情形']], ['退出条件'])),
    step("preStop sleep 5 加上应用优雅退出:2593 个请求失败 0 个,rollout 13 s。三种有保护的配置(三、四、五)在这个实验里都是 0 失败,差别要在别的场景里才看得出来;长连接就是一个(下一步)。", t=tl(S(5)), mark=lidx(S(5), '客户端请求 2593'), done=lidx(S(5), '客户端请求 2593'), b=bars([['请求总数', 2593, '2593'], ['失败', 0, '0']], 2593, done=[1], cur=[0]), kv=KV([['失败', '0 / 2593'], ['rollout 耗时', '13 s'], ['三、四、五', '都是 0 失败'], ['区分它们', '需要长连接等场景']], ['失败'])),
    step("长连接的客户端(复用连接,连接断了不自动重试,直接算一次失败)。preStop sleep 5 加应用立刻退出:2499 个请求失败 53 个(2.12%),全部是 reset,第一个到最后一个失败相隔 8.5 s。preStop 只让新连接不再进来,已建立的长连接仍然连在旧 Pod 上,进程退出时被重置。换成应用优雅退出(响应带 Connection: close,客户端换连接):2498 个请求失败 0 个。多数 HTTP 客户端库会对断开的空闲连接自动重试一次,这个实验的客户端没有,所以 53 是不带重试时的上限情形。", t=tl(S(6)), mark=lidx(S(6), 'keep-alive、readinessProbe + preStop sleep 5、应用立刻退出'), done=lidx(S(6), 'keep-alive、readinessProbe + preStop sleep 5 + 应用优雅退出'), b=bars([['长连接 + 立刻退出 请求', 2499, '2499'], ['长连接 + 立刻退出 失败(reset)', 53, '53(2.12%)'], ['长连接 + 优雅退出 请求', 2498, '2498'], ['长连接 + 优雅退出 失败', 0, '0']], 2499, mark=[1], done=[3], cur=[0, 2]), kv=KV([['立刻退出', '53 次 reset'], ['优雅退出 + Connection: close', '0 次失败'], ['preStop 管不到', '已建立的长连接'], ['客户端重试', '没有(上限情形)']], ['preStop 管不到'])),
]
